def count_ways(n, k):
    MOD = 10**9 + 7

    def inv(x):
        return pow(x, MOD - 2, MOD)

    def fact_mod(n):
        return factorial(n) % MOD

    def perm_mod(n, r):
        return fact_mod(n) * inv(fact_mod(n - r)) % MOD

    if k == 1:
        return perm_mod(n, n)

    # Calculate the number of ways to arrange the first k houses in a cycle including house 1
    cycle_k = perm_mod(k - 1, k - 2) * (k - 1) % MOD

    # Calculate the number of ways to arrange the remaining n-k houses without leading back to house 1
    linear_n_minus_k = perm_mod(n - k, n - k)

    # Total number of valid configurations
    total_ways = (cycle_k * linear_n_minus_k) % MOD

    return total_ways

