        return pow(n, n, MOD)

    dp = [[0] * (n + 1) for _ in range(n + 1)]
    dp[1][1] = 1

    for i in range(1, n + 1):
        for j in range(1, n + 1):
            if j != 1:
                dp[i][j] = dp[i - 1][1]
            else:
                dp[i][j] = sum(dp[i - 1]) % MOD

    result = 0
    for j in range(1, k + 1):
        result += dp[n][j]
    for j in range(k + 1, n + 1):
        result -= dp[n][j]
        result %= MOD

    return result

